INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist eine Netzwerkkarte erforderlich, um ein Gerät mit einem kabelgebundenen Netzwerk zu verbinden?', 2, '[{"text": "Ja", "correct": true, "because": "Sie ermöglicht die physische Verbindung"}, {"text": "Nein", "correct": false, "because": "Netzwerkkarte ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Netzwerkkarte gleichzeitig WLAN und Ethernet unterstützen?', 2, '[{"text": "Ja", "correct": true, "because": "Kombinierte Karten sind verfügbar"}, {"text": "Nein", "correct": false, "because": "Dual-Funktionskarten existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine Netzwerkkarte immer eine RJ45-Schnittstelle haben?', 2, '[{"text": "Nein", "correct": true, "because": "SFP oder andere Schnittstellen möglich"}, {"text": "Ja", "correct": false, "because": "Andere Typen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Geschwindigkeit einer Netzwerkkarte unabhängig vom Netzwerkstandard?', 2, '[{"text": "Nein", "correct": true, "because": "Muss mit z. B. Gigabit-Ethernet kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Standard beeinflusst Geschwindigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Können moderne Netzwerkkarten automatisch zwischen verschiedenen Geschwindigkeiten wechseln?', 2, '[{"text": "Ja", "correct": true, "because": "Auto-Negotiation ist Standard"}, {"text": "Nein", "correct": false, "because": "Automatische Anpassung üblich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle ist für eine Netzwerkkarte mit Glasfaserunterstützung typisch?', 2, '[{"text": "SFP", "correct": true, "because": "Small Form-factor Pluggable für Glasfaser"}, {"text": "RJ45", "correct": false, "because": "Für Twisted-Pair"}, {"text": "USB", "correct": false, "because": "Für externe Adapter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geschwindigkeit sollte eine Netzwerkkarte für ein modernes Heimnetzwerk mindestens unterstützen?', 3, '[{"text": "1 Gbit/s", "correct": true, "because": "Standard für Gigabit-Ethernet"}, {"text": "100 Mbit/s", "correct": false, "because": "Zu langsam"}, {"text": "10 Mbit/s", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat die MAC-Adresse einer Netzwerkkarte?', 2, '[{"text": "Eindeutige Identifikation", "correct": true, "because": "Hardware-Adresse"}, {"text": "IP-Adresszuweisung", "correct": false, "because": "Software-Ebene"}, {"text": "Routing", "correct": false, "because": "Router-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Netzwerkkarten-Typ wird für eine drahtlose Verbindung benötigt?', 2, '[{"text": "WLAN-Karte", "correct": true, "because": "Unterstützt drahtlose Standards"}, {"text": "Ethernet-Karte", "correct": false, "because": "Für Kabelverbindungen"}, {"text": "SFP-Karte", "correct": false, "because": "Für Glasfaser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft ist bei der Auswahl einer Netzwerkkarte für ein Rechenzentrum entscheidend?', 2, '[{"text": "10-Gbit/s-Unterstützung", "correct": true, "because": "Hohe Bandbreite nötig"}, {"text": "WLAN-Reichweite", "correct": false, "because": "Nicht für Rechenzentren"}, {"text": "Geringer Stromverbrauch", "correct": false, "because": "Sekundär"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sollte eine Netzwerkkarte für ein Unternehmensnetzwerk haben?', 4, '[{"text": "Hohe Geschwindigkeit", "correct": true, "because": "z. B. 1 Gbit/s oder 10 Gbit/s"}, {"text": "SFP-Unterstützung", "correct": true, "because": "Für Glasfaser"}, {"text": "Auto-Negotiation", "correct": true, "because": "Passt sich Netzwerk an"}, {"text": "Bluetooth", "correct": false, "because": "Nicht für Netzwerke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen können eine Netzwerkkarte unterstützen?', 3, '[{"text": "RJ45", "correct": true, "because": "Für Twisted-Pair"}, {"text": "SFP", "correct": true, "because": "Für Glasfaser"}, {"text": "PCIe", "correct": true, "because": "Für interne Verbindung"}, {"text": "HDMI", "correct": false, "because": "Für Video"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Auswahl einer Netzwerkkarte?', 4, '[{"text": "Netzwerkgeschwindigkeit", "correct": true, "because": "z. B. 1 Gbit/s"}, {"text": "Betriebssystemkompatibilität", "correct": true, "because": "Treiber nötig"}, {"text": "Verbindungstyp", "correct": true, "because": "Kabel oder WLAN"}, {"text": "Gewicht", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Netzwerkkarte mit 10 Gbit/s?', 3, '[{"text": "Schneller Datentransfer", "correct": true, "because": "Höhere Bandbreite"}, {"text": "Zukunftssicherheit", "correct": true, "because": "Für moderne Netze"}, {"text": "Geringere Latenz", "correct": true, "because": "Effizientere Verarbeitung"}, {"text": "Kleinere Größe", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Standards können eine WLAN-Netzwerkkarte unterstützen?', 3, '[{"text": "802.11ac", "correct": true, "because": "Wi-Fi 5"}, {"text": "802.11ax", "correct": true, "because": "Wi-Fi 6"}, {"text": "802.11n", "correct": true, "because": "Wi-Fi 4"}, {"text": "802.3", "correct": false, "because": "Für Ethernet"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine Netzwerkkarte mit SFP ist für Glasfaserverbindungen geeignet. b) Eine 1-Gbit/s-Karte ist für ein 10-Gbit/s-Netzwerk optimal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SFP ja, 1 Gbit/s zu langsam"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die MAC-Adresse ist eine eindeutige Kennung der Netzwerkkarte. b) Netzwerkkarten mit RJ45 sind nur für WLAN geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "MAC ja, RJ45 für Kabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Netzwerkkarte mit Auto-Negotiation passt sich der Netzwerkgeschwindigkeit an. b) Eine WLAN-Karte benötigt immer eine externe Antenne.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auto-Negotiation ja, Antenne optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine Netzwerkkarte mit 10 Gbit/s ist abwärtskompatibel zu 1 Gbit/s. b) Eine PCIe-Netzwerkkarte kann in einen USB-Port eingesteckt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abwärtskompatibel ja, PCIe nicht USB"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine WLAN-Karte mit 802.11ax ist für Wi-Fi 6 geeignet. b) Eine Netzwerkkarte muss immer eine RJ45-Schnittstelle haben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wi-Fi 6 ja, RJ45 nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

